repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('grand', 38), ('plaza', 16), ('grand', 17), ('grand', 39), ('plaza', 7), ('grand', 45), ('lodge', 48)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.reserve.py:
"""A pool of bookings with a remembered total."""


class BookingPool:
    def __init__(self):
        self._bookings = []
        self._total = None

    def add(self, booking):
        """Add one booking to the pool."""
        self._bookings.append(booking)
        self._total = None

    def remove(self, booking):
        """Take one booking out of the pool."""
        self._bookings.remove(booking)

    def total(self):
        """Return the total nights of the bookings in the pool."""
        if self._total is None:
            self._total = sum(x.nights for x in self._bookings)
        return self._total


def largest_nights(bookings):
    """Return the largest nights, or None when there are no bookings."""
    values = [x.nights for x in bookings]
    return max(values) if values else None
